    irs536: ['IRS Publication 536: net operating losses', 'https://www.irs.gov/publications/p536', 'method'],
    irc172: ['26 U.S.C. § 172: net operating loss deduction (80% of taxable income limit for post-2017 losses)', 'https://www.law.cornell.edu/uscode/text/26/172', 'method'],
    irc382: ['26 U.S.C. § 382: limit on loss carryforwards after an ownership change', 'https://www.law.cornell.edu/uscode/text/26/382', 'method'],
    irc11: ['26 U.S.C. § 11: US federal corporate tax rate (21%)', 'https://www.law.cornell.edu/uscode/text/26/11', 'method'],
    damCh9: ['Damodaran, Investment Valuation, chapter 9: measuring earnings (PDF)', 'https://pages.stern.nyu.edu/~adamodar/pdfiles/valn2ed/ch9.pdf', 'method'],
    damCh10: ['Damodaran, Investment Valuation, chapter 10: from earnings to cash flows (PDF)', 'https://pages.stern.nyu.edu/~adamodar/pdfiles/valn2ed/ch10.pdf', 'method'],
    damCh11: ['Damodaran, Investment Valuation, chapter 11: estimating growth (PDF)', 'https://pages.stern.nyu.edu/~adamodar/pdfiles/valn2ed/ch11.pdf', 'method'],
    damWC: ['Damodaran: working capital ratios by industry (US)', 'https://pages.stern.nyu.edu/~adamodar/New_Home_Page/datafile/wcdata.html', 'direct'],
    damCapex: ['Damodaran: capital expenditures, depreciation and reinvestment by industry (US)', 'https://pages.stern.nyu.edu/~adamodar/New_Home_Page/datafile/capex.html', 'direct'],
    damMargin: ['Damodaran: operating and net margins by industry (US)', 'https://pages.stern.nyu.edu/~adamodar/New_Home_Page/datafile/margin.html', 'direct'],
    damTax: ['Damodaran: effective tax rates by industry (US)', 'https://pages.stern.nyu.edu/~adamodar/New_Home_Page/datafile/taxrate.html', 'direct'],
    damRoc: ['Damodaran: return on capital and return on equity by industry (US)', 'https://pages.stern.nyu.edu/~adamodar/New_Home_Page/datafile/roc.html', 'direct'],
    damFund: ['Damodaran: fundamental growth in EBIT (reinvestment rate × return on capital) by industry', 'https://pages.stern.nyu.edu/~adamodar/New_Home_Page/datafile/fundgrEB.html', 'direct'],
    damRatings: ['Damodaran: interest coverage, synthetic ratings and default spreads', 'https://pages.stern.nyu.edu/~adamodar/New_Home_Page/datafile/ratings.html', 'direct'],
    damData: ['Damodaran Online: current data sets (all industry tables)', 'https://pages.stern.nyu.edu/~adamodar/New_Home_Page/datacurrent.html', 'direct'],
    sofr: ['FRED: Secured Overnight Financing Rate (base rate for most floating-rate loans)', 'https://fred.stlouisfed.org/series/SOFR', 'direct'],
    ust10: ['FRED: 10-year US Treasury yield', 'https://fred.stlouisfed.org/series/DGS10', 'direct'],
