  g('intInc', { t: 'Interest income', q: 'interest income', what: 'Interest earned on cash and short-term investments.', why: 'Large cash balances can earn meaningful income, which is not operating profit.', act: 'Investing surplus cash.',
    where: 'Statement of operations, "Interest income", or the other income note.', hist: 'As reported.', fc: 'Yield × opening (or average) cash and short-term investments. With average balances the model iterates until cash and interest agree.',
    fx: 'Income statement: below EBIT. Cash flow: through net income. Balance sheet: raises cash.', mis: ['Applying today’s yield for 10 years without looking at the rate outlook.'], dcf: 'Not in FCFF. Cash is added in the equity bridge instead.',
    f: 'Interest income(t) = yield × opening cash and STI (or the average)', ex: 'Opening cash 100 at 4% yields 4. ' + ILL, src: ['sofr'] });
